protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Blog>(entity =>
    {
        // Preserve EF8 discriminator property name (EF9 defaults to "$type")
        entity.HasDiscriminator<string>("Discriminator");

        // Preserve EF8 compound id format "Blog|1" (EF9 defaults to key-only)
        entity.HasRootDiscriminatorInJsonId(true);
    });
    // HasIndex removed — Cosmos DB provider now throws at startup.
    // Manage indexing via the container's indexing policy instead.
}

